/* Example using statfs to query the root filesystem '/' */
#include <stdio.h>
#include <sys/vfs.h>
#include <errno.h>
#include <string.h>
#include <stdlib.h>

#define TARGET_PATH "/"

int main(void) {
    struct statfs fs_stats;

    // Attempt to retrieve statistics for the root filesystem
    if (statfs(TARGET_PATH, &fs_stats) == -1) {
        fprintf(stderr, "statfs error on %s: %s\n", TARGET_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Filesystem Statistics for: %s\n", TARGET_PATH);
    printf("----------------------------------------\n");

    // Calculate total space in GB
    // f_blocks and f_bsize are typically unsigned long or similar large integer types
    double block_size = (double)fs_stats.f_bsize;
    double total_bytes = (double)fs_stats.f_blocks * block_size;
    double free_bytes = (double)fs_stats.f_bfree * block_size;

    printf("Optimal Block Size: %ld bytes\n", (long)fs_stats.f_bsize);
    printf("Total Capacity: %.2f GB\n", total_bytes / (1024.0 * 1024.0 * 1024.0));
    printf("Free Space: %.2f GB\n", free_bytes / (1024.0 * 1024.0 * 1024.0));
    printf("Total Inodes: %lu\n", (unsigned long)fs_stats.f_files);
    printf("Free Inodes: %lu\n", (unsigned long)fs_stats.f_ffree);

    return EXIT_SUCCESS;
}
